import crypto from 'node:crypto';
import type { Pool } from 'pg';

export interface HitlProposal {
  tenantId: string;
  workflowRunId: string;
  actionType: 'PO_PAYMENT' | 'ZNS_BROADCAST' | 'CRM_BULK_UPDATE';
  amountVnd: number;
  summaryDiff: string;
  frozenPayload: Record<string, unknown>;
  requiredRole: 'FINANCE_MANAGER' | 'OPS_DIRECTOR';
}

function hashCanonicalJson(obj: Record<string, unknown>): string {
  const canonical = JSON.stringify(obj, Object.keys(obj).sort());
  return crypto.createHash('sha256').update(canonical).digest('hex');
}

export async function createDurableCheckpoint(
  pool: Pool,
  proposal: HitlProposal,
  hmacSecret: string
) {
  const payloadSha256 = hashCanonicalJson(proposal.frozenPayload);
  const checkpointId = crypto.randomUUID();
  const expiresAt = new Date(Date.now() + 4 * 3600 * 1000); // Het han sau 4 gio

  await pool.query(
    `INSERT INTO hitl_checkpoints
      (id, tenant_id, workflow_run_id, action_type, payload_json, payload_sha256, required_role, status, expires_at)
     VALUES ($1, $2, $3, $4, $5, $6, $7, 'PENDING', $8)`,
    [
      checkpointId,
      proposal.tenantId,
      proposal.workflowRunId,
      proposal.actionType,
      JSON.stringify(proposal.frozenPayload),
      payloadSha256,
      proposal.requiredRole,
      expiresAt,
    ]
  );

  // Tao chu ky ngan gon gan vao nut bam Zalobot / ERP Card
  const approvalSig = crypto
    .createHmac('sha256', hmacSecret)
    .update(`${checkpointId}:${payloadSha256}:${proposal.tenantId}`)
    .digest('hex');

  return { checkpointId, payloadSha256, approvalSig, expiresAt };
}

export async function approveAndResumeWithAntiToctou(
  pool: Pool,
  params: { checkpointId: string; approverId: string; approverRole: string; sig: string },
  hmacSecret: string
) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // Khoa dong duy nhat de tranh 2 lan bam Duyet (Double-Spend / Double-ZNS)
    const res = await client.query(
      `SELECT id, tenant_id, payload_json, payload_sha256, required_role, status, expires_at
       FROM hitl_checkpoints
       WHERE id = $1 FOR UPDATE SKIP LOCKED`,
      [params.checkpointId]
    );
    const row = res.rows[0];
    if (!row) throw new Error('CONFLICT: Phien duyet dang duoc xu ly hoac khong ton tai.');
    if (row.status !== 'PENDING') throw new Error(`DENY: Trang thai hien tai la ${row.status}.`);
    if (new Date(row.expires_at) < new Date()) throw new Error('EXPIRED: Phieu da qua han 4 gio.');
    if (row.required_role !== params.approverRole) throw new Error('FORBIDDEN: Sai cap phe duyet.');

    const expectedSig = crypto
      .createHmac('sha256', hmacSecret)
      .update(`${row.id}:${row.payload_sha256}:${row.tenant_id}`)
      .digest('hex');
    if (!crypto.timingSafeEqual(Buffer.from(params.sig), Buffer.from(expectedSig))) {
      throw new Error('DENY: Chu ky phe duyet khong hop le.');
    }

    // Xac minh lai Hash chong TOCTOU truoc khi giao cho Execution Worker
    const recomputedHash = hashCanonicalJson(row.payload_json);
    if (recomputedHash !== row.payload_sha256) {
      throw new Error('SECURITY_ALERT: Payload da bi sua doi sau khi tao Checkpoint (TOCTOU).');
    }

    await client.query(
      `UPDATE hitl_checkpoints
       SET status = 'APPROVED', approved_by = $2, approved_at = now()
       WHERE id = $1`,
      [row.id, params.approverId]
    );
    await client.query('COMMIT');
    return { approvedPayload: row.payload_json, payloadSha256: row.payload_sha256 };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
